-- Keep original display names in metadata, not in new Storage object keys.
-- Match the Python v2 opaque-key contract at all database boundaries.
-- Forward-only: no source assets, committed keys, roles or RLS are changed.
-- V1 rows without storage_key_version retain their existing immutable paths.

alter table edoc.official_document_editor_storage_jobs
  drop constraint official_editor_storage_job_path_check;
alter table edoc.official_document_editor_storage_jobs
  add constraint official_editor_storage_job_path_check check (
    staging_bucket = 'edoc-private'
    and pg_catalog.btrim(staging_path) <> ''
    and final_bucket = 'edoc-private'
    and pg_catalog.btrim(final_path) <> ''
    and pg_catalog.btrim(token_expires_at) <> ''
