           and final_path = 'editor-final/' || document_id || '/' || asset_id || '/' || pg_catalog.upper(expected_sha256) || '.pdf')
          or (staging_path = 'editor/' || document_id || '/' || asset_id || '.png'
           and final_path = 'editor-final/' || document_id || '/' || asset_id || '/' || pg_catalog.upper(expected_sha256) || '.png')
          or (staging_path = 'editor/' || document_id || '/' || asset_id || '.jpg'
           and final_path = 'editor-final/' || document_id || '/' || asset_id || '/' || pg_catalog.upper(expected_sha256) || '.jpg')
        )
      )
